  const motionRows=['top','bottom'].map(key=>{
    const row=recordedMotion.rows[key];
    return {...row,min:Math.min(...row.path),max:Math.max(...row.path)};
  });
  // The reference is a shaped path, not a regular sine wave. Cubic interpolation
  // keeps both position and velocity continuous between measured samples.
  function referenceY(row,u){
    const points=row.path,last=points.length-1,p=u*last;
    if(p<0)return points[0]+p*(points[1]-points[0]);
    if(p>=last)return points[last]+(p-last)*(points[last]-points[last-1]);
    const i=Math.floor(p),t=p-i,a=points[i],b=points[i+1];
    const ma=i===0?b-a:(b-points[i-1])/2;
    const mb=i+1===last?b-a:(points[i+2]-a)/2;
    return (2*t*t*t-3*t*t+1)*a+(t*t*t-2*t*t+t)*ma+(-2*t*t*t+3*t*t)*b+(t*t*t-t*t)*mb;
  }
  const escape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
