    const music=document.getElementById('tsunBgMusic');
    const AudioContext=window.AudioContext||window.webkitAudioContext;
    let enabled=true,context=null,phrase=null,serial=0;
    const samples=new Map();
    let musicBase=null,musicFade=0;
    function clearMusicFade(){if(musicFade){window.clearInterval(musicFade);musicFade=0;}}
    function duckMusic(){
      if(!music||music.paused||music.muted)return;
      clearMusicFade();
      if(musicBase===null)musicBase=music.volume;
      music.volume=Math.min(musicBase,.22);
    }
    function restoreMusic(immediate=false){
      if(!music||musicBase===null)return;
      clearMusicFade();
      if(immediate){music.volume=musicBase;musicBase=null;return;}
      const from=music.volume,target=musicBase;let step=0;
      musicFade=window.setInterval(()=>{
        const progress=++step/8;
        music.volume=from+(target-from)*(1-Math.pow(1-progress,2));
        if(step===8){clearMusicFade();musicBase=null;}
      },25);
    }
    function stop(){
      ++serial;restoreMusic(document.hidden);
      if(!phrase||!context)return;
      const previous=phrase;phrase=null;
      const now=context.currentTime;
      previous.gain.gain.cancelScheduledValues(now);
      previous.gain.gain.setTargetAtTime(0,now,.008);
      previous.sources.forEach(source=>{try{source.stop(now+.04);}catch(error){}});
    }
    function prepare(){
      if(!context||context.state==='closed'){context=new AudioContext();samples.clear();}
    }
    function sampleFor(name){
      if(samples.has(name))return samples.get(name);
      const voice=voices[name]||voices.Labo;
      const bytes=atob(voice.pcm),frames=bytes.length/2;
      const sample=context.createBuffer(1,frames,voice.rate);
      const channel=sample.getChannelData(0);
      for(let i=0;i<frames;i++){
        const value=bytes.charCodeAt(i*2)|(bytes.charCodeAt(i*2+1)<<8);
        channel[i]=(value>=32768?value-65536:value)/32768;
      }
      samples.set(name,sample);return sample;
    }
    function speak(dog,ticket){
      if(ticket!==serial||!enabled||document.hidden||context.state!=='running')return;
      const source=context.createBufferSource(),gain=context.createGain();
      // The complete individual clip already contains its pitch, timbre and rhythm.
      source.buffer=sampleFor(dog.name);
      gain.gain.value=.95;
      source.connect(gain);gain.connect(context.destination);
      const current={gain,sources:[source]};phrase=current;
      source.onended=()=>{
        source.disconnect();gain.disconnect();
        if(phrase===current){phrase=null;restoreMusic();}
      };
      duckMusic();source.start(context.currentTime+.012);
    }
