    // upper or lower colour, including the last/first pair at the loop seam.
    const keys=[
      'green1','grey6','orange3','pink5','red7','white1','yellow1',
      'green2','grey1','orange1','pink1','red1','yellow3','white2',
      'yellow2','grey2','pink2','orange2','red2','white3','green4',
      'pink3','grey3','red3','orange4','white4','green6','yellow4',
      'pink4','grey4','orange5','red4','green5','white5','yellow6',
      'grey5','orange6','pink6','red5','white6','green7','yellow5',
      'grey7','orange7','red6','pink7','green3','yellow7','white7'
    ];
    const rail=document.getElementById('tsunBookRail');
    const chips=document.getElementById('tsunBookSeriesButtons');
    const dogVoice=createBookDogVoice();
    // Use the homepage's actual dog/name/coat mapping, keyed by its board colour.
    const castByBoard=new Map(configs.map((dog,index)=>[dog.base,{...dog,index}]));
    const portraitCache=new Map(),portraitURLs=[];
